#include "ui_objects.h"
#include "aic_ui.h"
#include "ui_util.h"



void screen_4_Area_create(ui_manager_t *ui)
{
    screen_4_Area_t *scr = screen_4_Area_get(ui);

    /* Always reuse. auto_del=true leaked a new 1280x800 root on every AA 06. */
    if (scr->obj) {
        return;
    }

    // Init scr->obj
    scr->obj = lv_obj_create(NULL);
    lv_obj_set_scrollbar_mode(scr->obj, LV_SCROLLBAR_MODE_OFF);

    /* Black, not 0xfcfcfc: hide-image / first-PNG gap would flash white. */
    lv_obj_set_style_bg_color(scr->obj, lv_color_hex(0x000000), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_bg_opa(scr->obj, LV_OPA_COVER, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_pad_all(scr->obj, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_border_width(scr->obj, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_radius(scr->obj, 0, LV_PART_MAIN | LV_STATE_DEFAULT);


}


